/**
 * Lot Chooses
 * -----------
 * Abram and Lot part ways as their herdsmen quarrel; Lot lifts his eyes to the well-watered Jordan plain and takes it. Stage: a wide hilltop overlooking the green Jordan valley and the distant soot of Sodom; Abram generous and calm, Lot eager; midday glare on the plain, shade on the heights.
 *
 * Palette 0xd8b878 → 0x9c8456 · light: dawn · hero: well
 * Game beat: Survey the land and give Lot first choice.
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./abraham-kit.js.
 */

import { THREE, createScene, water, cityGate, house, well, person, birds } from './abraham-kit.js';

const BG = 0xd8b878;
const GROUND = 0x776542;

export function build(group) {
    const W = createScene(group, { seed: 1215074627, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x2a2317, 0xb39863);
    W.ground(260, 95, 0, 60, 0x776542, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x655638, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x413824), [0, -0.05, -14.6]);

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [-20, 0, -58], { name: 'city', r: [0, 0.05, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0xa48b5a, trim: 0x5f5135 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x947d52 });
    }
    W.backdrop(city);

    /* hero: the well */
    well(W, group, 0, 0, 11, 1.2);
    W.disc([0, 5, 1], 4, 0xffef9c, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0xd8b878, ry: 0.07, s: 1.03 });

    /* birds: slow circles high above */
    birds(W, group, 7, 55, { y: 26 });

    return W.finish();
}

export default { build };
